"""Generate a deterministic, ASCII-punctuation ambient chat pack and idempotent SQL.
The 10,000 variants combine authored contextual openers and conversational codas;
they are not represented as 10,000 independently authored sentences.
Run from repository root. No account, character or credential data is read.
"""
import json, hashlib, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
# Existing hook names: placeholders are supplied by BroadcastHelper, not guessed IDs.
GROUPS={
'suggest_something': '''Anyone else lose track of time in %zone_name?|I came to %zone_name for one thing and forgot what it was.|My bags are full and somehow none of it is useful.|The real endgame is finding space in the bank.|I swear that mailbox was closer yesterday.|Which is harder, a raid boss or choosing a transmog?|I need a mount that also carries my repair bill.|Every time I clean my bags I find another quest item.|Fishing is relaxing until someone asks what I caught.|Is there a profession for getting lost?|My hearthstone is always on cooldown when I need it.|Azeroth needs more benches near the auction house.|One more quest turned into an entire evening.|I should stop checking auctions and actually play.|The music in %zone_name is doing most of the work tonight.|I spend more time choosing mounts than riding them.|Anyone got a favorite place to fish?|Sometimes a quiet lap around town is the whole plan.|I have enough cooking ingredients to open an inn.|My bank alt needs a bank alt.''',
'suggest_trade': '''Anyone farming %category?|Are %category prices always like this?|Thinking of spending tonight gathering %category.|Where do people farm %category these days?|Anyone else working on %category?|Trying to decide whether to farm %category or just save gold.|The market for %category keeps changing.|I need to stop ignoring %category when I see it.|Anyone have a good route for %category?|Gathering %category beats staring at the bank.|How much time do you spend farming %category?|I keep checking the prices for %category.|Would be nice to find a quiet spot for %category.|People still farm %category themselves, right?|Anyone want to compare gathering routes for %category?|Taking the scenic route while looking for %category.|I should have kept more %category last week.|The profession shopping list says %category again.|Apparently my next project needs more %category.|Looking for advice on gathering %category.''',
'suggest_sell': '''WTS %item_formatted_link, %cost_gold.|Got %item_formatted_link available for %cost_gold.|Anyone looking for %item_formatted_link? Asking %cost_gold.|Selling %item_formatted_link at %cost_gold.|%item_formatted_link available, price %cost_gold.|Clearing some bag space: %item_formatted_link for %cost_gold.|Price check while I offer %item_formatted_link at %cost_gold.|If you need %item_formatted_link, mine is %cost_gold.|Offering %item_formatted_link for %cost_gold.|Today's spare materials: %item_formatted_link, %cost_gold.|Offering spare %item_formatted_link at %cost_gold.|My %item_formatted_link is available for %cost_gold.|Looking for a buyer for %item_formatted_link at %cost_gold.|Selling this batch of %item_formatted_link for %cost_gold.|%item_formatted_link for sale, asking %cost_gold today.|Before I head out: %item_formatted_link, %cost_gold.|Sale offer: %item_formatted_link at %cost_gold.|Got a spare %item_formatted_link to sell for %cost_gold.|Anyone after %item_formatted_link at %cost_gold?|Offering %item_formatted_link now, %cost_gold.''',
'suggest_instance': '''Anyone up for %instance_name?|Looking for a group for %instance_name.|Anyone still running %instance_name?|Thinking about a run through %instance_name.|Anyone need a %my_role for %instance_name?|How are the queues for %instance_name tonight?|Could go for %instance_name if a group is forming.|Anyone learning %instance_name?|Looking for company for %instance_name.|Is anyone organizing %instance_name?|Would be nice to get a group for %instance_name.|Anyone want to plan a run of %instance_name?|%my_role looking into %instance_name.|Might run %instance_name instead of staring at auctions.|Anyone got tips for %instance_name?|I keep meaning to run %instance_name.|Who else needs %instance_name?|A relaxed run of %instance_name sounds good.|Anyone interested in %instance_name later?|Trying to find people for %instance_name.''',
'suggest_quest': '''Anyone else doing %quest_link?|Looking for company for %quest_link.|Anyone working through %quest_link?|Could use a second pair of hands for %quest_link.|Heading out for %quest_link.|Anyone know the route for %quest_link?|Trying to get %quest_link sorted.|Who else has %quest_link in their log?|Anyone nearby interested in %quest_link?|I keep putting off %quest_link.|Time to make some progress on %quest_link.|Anyone want to work on %quest_link together?|Checking whether anyone needs %quest_link.|Thinking about tackling %quest_link next.|%quest_link is on my list tonight.|Looking around for others on %quest_link.|Anyone have advice for %quest_link?|Would be good to group for %quest_link.|Still working on %quest_link here.|Seeing if anyone wants to help with %quest_link.''',
'suggest_faction': '''Anyone else working on %faction rep?|Thinking of spending some time on %faction.|How is everyone finding the %faction grind?|I should stop neglecting %faction reputation.|Anyone have tips for %faction?|Trying to make some progress with %faction.|Is %faction on anyone else's list?|Another evening thinking about %faction rep.|Would be nice to finish the %faction grind eventually.|Who else is doing %faction reputation?|I keep checking the rewards for %faction.|Considering a few more runs for %faction.|Anyone want to compare notes on %faction?|I need a better routine for %faction.|The %faction reputation bar is looking long.|I should pick a reputation and stick with it. Maybe %faction.|Looking for advice on raising %faction rep.|Anyone remember their first %faction grind?|%faction is my current distraction.|Making a plan for %faction instead of spending more gold.''',
'broadcast_quest_turned_in': '''Turned in %quest_link.|%quest_link handed in at last.|Done with %quest_link.|That's %quest_link out of the log.|Finished turning in %quest_link.|Back from %quest_link.|%quest_link is wrapped up.|Just handed over %quest_link.|Made it back to turn in %quest_link.|%quest_link complete and turned in.|Another one down: %quest_link.|Finally handed in %quest_link.|Quest log has one less entry: %quest_link.|Got %quest_link turned in.|The turn-in for %quest_link is done.|Managed to finish %quest_link.|%quest_link taken care of.|Just finished up %quest_link.|Back in town after %quest_link.|Turn-in done for %quest_link.''',
'broadcast_looting_item_normal': '''Picked up %item_link.|Found %item_link along the way.|Another %item_link for the bags.|Well, there's %item_link.|Got %item_link out of that.|A little %item_link never hurts.|Loot today includes %item_link.|%item_link is coming home with me.|Looks like %item_link this time.|Adding %item_link to the collection.|Bags just gained %item_link.|Just found %item_link.|Today's find: %item_link.|Taking %item_link back to town.|Found myself some %item_link.|%item_link turned up.|More %item_link for later.|Picked myself up %item_link.|That's %item_link accounted for.|Got a bit of loot: %item_link.''',
'broadcast_quest_accepted_generic': '''Picked up %quest_link.|Time to have a look at %quest_link.|Adding %quest_link to the plan.|Off to work on %quest_link.|Got %quest_link in the log now.|Next stop is %quest_link.|Going to try %quest_link.|Starting on %quest_link.|Apparently I'm doing %quest_link now.|Let's see about %quest_link.|Another task: %quest_link.|Looks like %quest_link is next.|Taking a shot at %quest_link.|Making room in the evening for %quest_link.|New plan involves %quest_link.|Just accepted %quest_link.|Heading toward %quest_link.|%quest_link is the next distraction.|Got a lead on %quest_link.|Trying something new with %quest_link.''',
'party_flavor': '''Anyone need a quick break?|Ready when everyone is ready.|Let's keep an eye on patrols.|Those repair bills add up.|I'd rather wait than pull an extra pack.|Sometimes the floor really is the hardest boss.|Anyone else always forget to empty their bags?|A clean pull beats a fast wipe.|Let's leave room to move.|Getting lost is part of the dungeon experience.|The scenery is nicer when it isn't trying to kill us.|I always remember the shortcut after we pass it.|A moment to regroup never hurts.|We can take this at our own pace.|No prize for standing in the fire.|Some of these corridors all look the same.|I'm more worried about the next patrol than the boss.|I'd take a map over another grey item.|Interrupts make life a lot easier.|A little patience saves a lot of walking back.'''
}
CODAS='''Anyone else feel that?|That's the plan, anyway.|No rush on my end.|Taking my time tonight.|One thing at a time.|Could be worse.|Keeping it simple for now.|We'll see how it goes.|Still better than sorting the bank.|There goes my evening.|Back to it in a moment.|Trying not to overthink it.|Some days are like that.|Nothing fancy tonight.|Maybe I should get some coffee.|I probably need a better plan.|At least the music is good.|Small steps count.|That's enough excitement for a minute.|Time flies in this game.|So much for a quick session.|I keep telling myself this will be quick.|It sounded simpler earlier.|Not a bad way to spend the evening.|I could use a snack.|My bags disagree with my plans.|At least it's not another repair bill.|Tomorrow's problem can wait.|Trying to stay organized.|It's the little things.|One distraction after another.|No wonder my hearth is always on cooldown.|I should probably check the time.|This game eats entire evenings.|I really should clear my quest log.|Somehow there's always another errand.|Better than staring at the login screen.|No complaints about the company.|I might have said that yesterday too.|Still having a good time.|The bank can wait.|I need to stop opening the map every ten seconds.|Another normal day in Azeroth.|I should have brought more bag space.|I'll pretend this was planned.|Could use a quiet evening for once.|There's always something else to do.|Apparently this is my hobby now.|I blinked and another hour went by.|Good enough for tonight.'''.split('|')
rows=[]
for name,heads in GROUPS.items():
 heads=heads.split('|');assert len(heads)==20,(name,len(heads))
 for h in heads:
  for t in CODAS:rows.append(dict(name=name,text=h+' '+t))
assert len(rows)==10000 and len({(r['name'],r['text']) for r in rows})==10000
assert all(r['text'].isascii() and len(r['text'])<255 for r in rows)
p=ROOT/'modules/mod_playerbots/data/chat/ambient_en_10000.json';p.write_text(json.dumps(rows,indent=2)+'\n',encoding='utf-8')
def hx(s):return 'CONVERT(0x'+s.encode().hex()+' USING utf8mb4)'
sql=['-- Playerbots database only. Deterministic authored-clause combinations; no private data.', '-- Existing chat frequency/probabilities are unchanged. Rerunning does not duplicate rows.', 'START TRANSACTION;', 'CREATE TEMPORARY TABLE bot_chat_seed (name VARCHAR(255), text VARCHAR(1024)) CHARACTER SET utf8mb4;', 'CREATE TEMPORARY TABLE bot_chat_existing (digest BINARY(32) PRIMARY KEY);', 'INSERT IGNORE INTO bot_chat_existing SELECT UNHEX(SHA2(CONCAT(name,CHAR(0),text),256)) FROM ai_playerbot_texts;']
for i in range(0,len(rows),200):sql.append('INSERT INTO bot_chat_seed VALUES\n'+',\n'.join('('+hx(r['name'])+','+hx(r['text'])+')' for r in rows[i:i+200])+';')
sql += ['INSERT INTO ai_playerbot_texts (name,text,say_type,reply_type) SELECT s.name,s.text,0,0 FROM bot_chat_seed s WHERE NOT EXISTS (SELECT 1 FROM bot_chat_existing e WHERE e.digest=UNHEX(SHA2(CONCAT(s.name,CHAR(0),s.text),256)));', 'DROP TEMPORARY TABLE bot_chat_seed;', 'DROP TEMPORARY TABLE bot_chat_existing;', 'COMMIT;']
q=ROOT/'modules/mod_playerbots/data/sql/playerbots/2026_11_12_01_ambient_chat_pack.sql';q.parent.mkdir(parents=True,exist_ok=True);q.write_text('\n'.join(sql)+'\n',encoding='ascii')
print(json.dumps(dict(variants=len(rows),categories=len(GROUPS),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),longest=max(len(r['text']) for r in rows))))
